//! Compatibility tests against the fixture generated by the Go implementation.

use std::path::PathBuf;

use pm_updates::{check_sha256_sum, validate_artifact_filename, Artifact, Index, Version};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/updates.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn parse_index(json: &str) -> Index {
    Index::parse(json.as_bytes(), "linux_amd64", None).unwrap()
}

fn temp_dir(tag: &str) -> PathBuf {
    let mut path = std::env::temp_dir();
    path.push(format!(
        "pm-updates-{tag}-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .subsec_nanos()
    ));
    let _ = std::fs::remove_dir_all(&path);
    std::fs::create_dir_all(&path).unwrap();
    path
}

#[test]
fn parsed_indexes_match_go() {
    let fixture = fixture();
    let index_json = fixture["index_json"].as_str().unwrap();

    for platform in ["linux_amd64", "windows_amd64"] {
        let index = Index::parse(index_json.as_bytes(), platform, None).unwrap();
        let expected = &fixture["parsed"][platform];

        assert_eq!(index.name, expected["name"].as_str().unwrap());
        assert_eq!(index.version, expected["version"].as_str().unwrap());
        assert_eq!(
            index.version_num.as_ref().unwrap().to_string(),
            "1.2.3",
            "{platform}"
        );
        assert!(index.published > 0);

        let artifacts = expected["artifacts"].as_array().unwrap();
        assert_eq!(index.artifacts.len(), artifacts.len(), "{platform}");
        for (artifact, expected) in index.artifacts.iter().zip(artifacts) {
            assert_eq!(artifact.filename, expected["filename"].as_str().unwrap());
            assert_eq!(artifact.sha256, expected["sha256"].as_str().unwrap());
            assert_eq!(artifact.unpack, expected["unpack"].as_str().unwrap());
            assert_eq!(artifact.platform, expected["platform"].as_str().unwrap());
            assert_eq!(artifact.version, expected["version"].as_str().unwrap());
            assert!(artifact.version_num.is_some());
            assert!(artifact.path().is_empty(), "no local path before export");
        }
    }

    // Platform-specific file modes.
    let index = Index::parse(index_json.as_bytes(), "linux_amd64", None).unwrap();
    let linux = index
        .artifacts
        .iter()
        .find(|artifact| artifact.filename == "linux.zip")
        .unwrap();
    assert_eq!(linux.get_file_mode(), 0o755);
    assert_eq!(index.artifacts[0].get_file_mode(), 0o644);
    assert_eq!(linux.to_string(), "linux.zip(vv1.2.2)");

    // Exporting attaches a local path and keeps versions.
    let exported = linux.export("/tmp/updates", index.version_num.as_ref());
    assert_eq!(exported.path(), "/tmp/updates/linux.zip");
    assert_eq!(exported.semver().unwrap().to_string(), "1.2.2");
}

#[test]
fn filename_validation_matches_go() {
    let fixture = fixture();
    for case in fixture["filenames"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let result = validate_artifact_filename(name);
        let ok = case["ok"].as_bool().unwrap();
        assert_eq!(result.is_ok(), ok, "{name:?}");
        if let Err(error) = result {
            assert_eq!(
                error.to_string(),
                case["error"].as_str().unwrap(),
                "{name:?}"
            );
        }
    }
}

#[test]
fn upgrade_eligibility_matches_go() {
    let fixture = fixture();
    for case in fixture["eligibility"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let index = parse_index(case["index_json"].as_str().unwrap());
        // The future case is evaluated exactly one hour after its publication.
        let now = if name == "future" {
            index.published - 3600
        } else {
            index.published
        };

        let result = index.can_do_upgrades(now);
        assert_eq!(result.is_ok(), case["ok"].as_bool().unwrap(), "{name}");
        if let Err(error) = result {
            assert_eq!(error.to_string(), case["error"].as_str().unwrap(), "{name}");
        }
    }
}

#[test]
fn upgrade_decisions_match_go() {
    let fixture = fixture();
    for case in fixture["upgrade_cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let current = parse_index(case["current_json"].as_str().unwrap());
        let new = parse_index(case["new_json"].as_str().unwrap());
        let now = current.published.max(new.published) + 3600;

        let result = current.should_upgrade_to(&new, now);
        assert_eq!(result.is_ok(), case["ok"].as_bool().unwrap(), "{name}");
        match result {
            Ok(()) => {}
            Err(error) => {
                assert_eq!(error.to_string(), case["error"].as_str().unwrap(), "{name}");
                if name == "same-index" {
                    assert!(error.is_same_index());
                }
            }
        }
    }
}

#[test]
fn versions_match_go() {
    let fixture = fixture();
    for case in fixture["versions"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        let result = Version::parse(input);
        let ok = case["ok"].as_bool().unwrap();
        assert_eq!(result.is_ok(), ok, "{input:?}");
        if let Ok(version) = result {
            assert_eq!(
                version.to_string(),
                case["parsed"].as_str().unwrap(),
                "{input:?}"
            );
        }
    }
}

#[test]
fn version_comparisons_match_go() {
    let fixture = fixture();
    for case in fixture["comparisons"].as_array().unwrap() {
        let a = Version::parse(case["a"].as_str().unwrap()).unwrap();
        let b = Version::parse(case["b"].as_str().unwrap()).unwrap();
        let result = match a.cmp(&b) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        };
        assert_eq!(
            result,
            case["result"].as_i64().unwrap() as i32,
            "{} vs {}",
            case["a"],
            case["b"]
        );
    }
}

#[test]
fn sha256_checks_match_go() {
    let fixture = fixture();
    for case in fixture["sha256"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let data = case["data"].as_str().unwrap().as_bytes();
        let hash = case["sha256"].as_str().unwrap();

        let result = check_sha256_sum(data, hash);
        assert_eq!(result.is_ok(), case["ok"].as_bool().unwrap(), "{name}");
        if let Err(error) = result {
            let expected = match name {
                "invalid-hex" => format!("invalid hex encoding for expected hash {hash}"),
                "wrong-size" => format!("invalid size for expected hash {hash}"),
                _ => "sha256sum mismatch".to_string(),
            };
            assert_eq!(error.to_string(), expected, "{name}");
        }
    }
}

#[test]
fn artifacts_are_verified_on_disk() {
    let fixture = fixture();
    let ok_case = fixture["sha256"]
        .as_array()
        .unwrap()
        .iter()
        .find(|case| case["name"] == "ok")
        .unwrap();
    let hash = ok_case["sha256"].as_str().unwrap();

    let dir = temp_dir("artifacts");
    std::fs::write(dir.join("portmaster"), b"portmaster").unwrap();

    let index = Index {
        name: "test-index".to_string(),
        version: "v1.0.0".to_string(),
        published: 1,
        artifacts: vec![Artifact {
            filename: "portmaster".to_string(),
            sha256: hash.to_string(),
            ..Artifact::default()
        }],
        ..Index::default()
    };
    index.verify_artifacts(&dir).unwrap();

    // A corrupted file is reported with the artifact name.
    std::fs::write(dir.join("portmaster"), b"tampered").unwrap();
    let error = index.verify_artifacts(&dir).unwrap_err();
    assert_eq!(error.to_string(), "verify portmaster: sha256sum mismatch");

    // A missing file is reported as well.
    std::fs::remove_file(dir.join("portmaster")).unwrap();
    assert!(index.verify_artifacts(&dir).is_err());
}

#[test]
fn indexes_can_be_verified_and_loaded() {
    let fixture = fixture();
    let index_json = fixture["index_json"].as_str().unwrap();

    // Without a verifier the index is accepted.
    assert!(Index::parse(index_json.as_bytes(), "linux_amd64", None).is_ok());

    // A verifier can reject the index.
    let reject = |_: &[u8]| Err("bad signature".to_string());
    let error = Index::parse(index_json.as_bytes(), "linux_amd64", Some(&reject)).unwrap_err();
    assert_eq!(error.to_string(), "verify: bad signature");

    let accept = |content: &[u8]| {
        if content.is_empty() {
            Err("empty".to_string())
        } else {
            Ok(())
        }
    };
    assert!(Index::parse(index_json.as_bytes(), "linux_amd64", Some(&accept)).is_ok());

    // Loading from disk and serializing back.
    let dir = temp_dir("index");
    let path = dir.join("index.json");
    std::fs::write(&path, index_json).unwrap();
    let index = Index::load(&path, "linux_amd64", None).unwrap();
    assert_eq!(index.name, "test-index");

    let serialized = index.to_json().unwrap();
    let reparsed = Index::parse(&serialized, "linux_amd64", None).unwrap();
    assert_eq!(reparsed.artifacts.len(), index.artifacts.len());
    assert_eq!(reparsed.version, index.version);
    assert_eq!(reparsed.published, index.published);

    // Missing files report a read error.
    assert!(Index::load(dir.join("missing.json"), "linux_amd64", None).is_err());
}

#[test]
fn artifacts_are_compared_by_version() {
    let old = Artifact {
        filename: "old.zip".to_string(),
        version: "v1.0.0".to_string(),
        version_num: Some(Version::parse("1.0.0").unwrap()),
        ..Artifact::default()
    };
    let new = Artifact {
        filename: "new.zip".to_string(),
        version: "v1.2.0".to_string(),
        version_num: Some(Version::parse("1.2.0").unwrap()),
        ..Artifact::default()
    };
    let unknown = Artifact {
        filename: "unknown.zip".to_string(),
        ..Artifact::default()
    };

    assert_eq!(new.is_newer_than(&old), (true, true));
    assert_eq!(old.is_newer_than(&new), (false, true));
    // Go returns (false, false) when the *other* artifact has no parsed
    // version: the comparison cannot be made.
    assert_eq!(new.is_newer_than(&unknown), (false, false));
    assert_eq!(unknown.is_newer_than(&new), (false, false));
}
